import React, { useState, useEffect } from "react";
import Confetti from "react-confetti";
import "./App.css";

// 1. DATA DEFINITIONS (Categories, Images, Services, Packages & Testimonials)
const CATEGORIES = [
  "All", "Wedding", "Birthday", "Portrait", "Fashion", "Product", "Events", "Nature", "Travel"
];

const GALLERY_IMAGES = [
  { id: 1, title: "13333 avif", category: "Nature", filename: "13333.avif" },
  { id: 2, title: "Nature Detail DIA8277", category: "Nature", filename: "Buchenschleimru_blinge_DIA8277.jpg" },
  { id: 3, title: "Rose Macro", category: "Nature", filename: "close-up-of-blossoming-rose-flower-royalty-free-image-1580852839.jpg" },
  { id: 4, title: "Majestic Owl", category: "Nature", filename: "H3NNfqPvagSQ9zI6cwjDRq.jpg" },
  { id: 5, title: "hero-bg", category: "Nature", filename: "hero-bg.jpg" },
  { id: 6, title: "Travel Path (1)", category: "Travel", filename: "images (1).jpg" },
  { id: 7, title: "Landscape View (2)", category: "Nature", filename: "images (2).jpg" },
  { id: 8, title: "Coastal Town (3)", category: "Travel", filename: "images (3).jpg" },
  { id: 9, title: "River Stream (4)", category: "Nature", filename: "images (4).jpg" },
  { id: 10, title: "Wild Elephant (5)", category: "Nature", filename: "images (5).jpg" },
  { id: 11, title: "Desert Lizard (6)", category: "Nature", filename: "images (6).jpg" },
  { id: 12, title: "Portrait Study (7)", category: "Portrait", filename: "images (7).jpg" },
  { id: 13, title: "Green Hills Landscape", category: "Travel", filename: "images.jpg" },
  { id: 14, title: "High Res Nature Background", category: "Nature", filename: "nature-background-high-resolution-wallpaper-for-a-serene-and-calming-vibe-free-photo.jpg" },
  { id: 15, title: "Mystic Pathway", category: "Nature", filename: "pexels-ankit-rainloure-1425442-35771810.jpg" },
  { id: 16, title: "Red Bird", category: "Nature", filename: "pexels-dmytkopl-38601716.jpg" },
  { id: 17, title: "Autumn Tree Avenue", category: "Nature", filename: "pexels-efrem-efre-2786187-29046353.jpg" },
  { id: 18, title: "Forest Light", category: "Nature", filename: "pexels-josh-a-d-4467879-16636173.jpg" },
  { id: 19, title: "Floral Portrait", category: "Portrait", filename: "pexels-khadija-qasanova-376394062-20295105.jpg" },
  { id: 20, title: "Coastal Cliff", category: "Travel", filename: "photo-1544954617-f5c6b0d16164.jpg" },
  { id: 21, title: "Botanical Garden", category: "Nature", filename: "photo-1457089328109-e5d9bd499191.jpg" },
  { id: 22, title: "Golden Hour Valley", category: "Nature", filename: "photo-1472214103451-9374bd1c798e.jpg" },
  { id: 23, title: "Wild Orange Blossoms", category: "Nature", filename: "photo-1684087554249-0021c9c85fc9.jpg" },
  { id: 24, title: "Purple Canopy Forest", category: "Nature", filename: "photo-1693985007521-e08e64770947.jpg" },
  { id: 25, title: "Blue Hour Meadow", category: "Nature", filename: "photo-1695004672476-0c1e8d7a7e79.jpg" },
  { id: 26, title: "Fashion Model Premium", category: "Fashion", filename: "premium_photo-1679064458881-76904cf6d1aa.jpg" },
  { id: 27, title: "Sunset Ball", category: "Events", filename: "Sunset-ball.jpg" },
  { id: 28, title: "Red Flowers Macro", category: "Product", filename: "types-of-red-flowers-geranium.jpg" },
  { id: 29, title: "Wildlife Photography", category: "Nature", filename: "Wildlife+Photography+by+Kathy+Karn+01.jpg" },
  { id: 30, title: "Birthday Celebration", category: "Birthday", filename: "hero-bg.jpg" }
];

const SERVICES = [
  { title: "Wedding Photography", desc: "Capturing your special day with elegance." },
  { title: "Birthday & Parties", desc: "Fun & lively event coverage for all ages." },
  { title: "Portrait Shoots", desc: "Studio & outdoor personal profile photos." },
  { title: "Fashion & Commercial", desc: "High-end lookbooks and model portfolios." },
  { title: "Product Photography", desc: "E-commerce & high quality product displays." },
  { title: "Corporate Events", desc: "Professional coverage for seminars & galas." }
];

const PACKAGES = [
  { id: "basic", name: "Basic", price: 150, features: ["2 Hours Coverage", "15 Edited Photos", "Online Gallery"] },
  { id: "standard", name: "Standard", price: 350, features: ["5 Hours Coverage", "40 Edited Photos", "Print Rights", "1 Frame"] },
  { id: "premium", name: "Premium", price: 750, features: ["Full Day Coverage", "100+ Edited Photos", "Photo Album", "Drone Shots"] },
  { id: "custom", name: "Custom", price: 200, features: ["Tailored Services", "Flexible Hours", "Custom Deliverables"] }
];

const TESTIMONIALS = [
  { name: "Ali Ahmed", quote: "Amazing photos! Truly captured the spirit of our wedding day perfectly." },
  { name: "Sara Khan", quote: "The portrait session was quick, fun, and very professional." },
  { name: "Usman Raza", quote: "Best photography team in town! Highly recommend their packages." }
];

const getImagePath = (filename) => process.env.PUBLIC_URL + `/images/${filename}`;

// 2. MAIN APP COMPONENT
export default function App() {
  const [activeTab, setActiveTab] = useState("home");
  const [darkMode, setDarkMode] = useState(false);
  const [menuOpen, setMenuOpen] = useState(false);

  // Gallery Search & Category State
  const [searchQuery, setSearchQuery] = useState("");
  const [selectedCategory, setSelectedCategory] = useState("All");
  const [activeLightbox, setActiveLightbox] = useState(null);

  // Favorites in LocalStorage
  const [favorites, setFavorites] = useState(() => {
    const saved = localStorage.getItem("fav_photos");
    return saved ? JSON.parse(saved) : [];
  });

  // Slider State
  const [currentSlide, setCurrentSlide] = useState(0);

  // Login & Confetti State
  const [isLoggedIn, setIsLoggedIn] = useState(false);
  const [showLoginModal, setShowLoginModal] = useState(false);
  const [loginForm, setLoginForm] = useState({ username: "", password: "" });
  const [runConfetti, setRunConfetti] = useState(false);

  // Booking & Calculator State
  const [selectedPackage, setSelectedPackage] = useState(PACKAGES[0]);
  const [extraHours, setExtraHours] = useState(0);
  const [droneAddon, setDroneAddon] = useState(false);
  const [albumAddon, setAlbumAddon] = useState(false);
  const [bookingDetails, setBookingDetails] = useState({ name: "", email: "", date: "", time: "", category: "Wedding" });
  const [bookingPopup, setBookingPopup] = useState(false);

  // Contact State
  const [contactMsg, setContactMsg] = useState({ name: "", email: "", message: "" });
  const [contactSubmitted, setContactSubmitted] = useState(false);

  useEffect(() => {
    localStorage.setItem("fav_photos", JSON.stringify(favorites));
  }, [favorites]);

  useEffect(() => {
    if (darkMode) {
      document.body.classList.add("dark-mode");
    } else {
      document.body.classList.remove("dark-mode");
    }
  }, [darkMode]);

  useEffect(() => {
    const timer = setInterval(() => {
      setCurrentSlide((prev) => (prev + 1) % 5);
    }, 4000);
    return () => clearInterval(timer);
  }, []);

  const toggleFavorite = (id) => {
    setFavorites((prev) =>
      prev.includes(id) ? prev.filter((item) => item !== id) : [...prev, id]
    );
  };

  const handleLoginSubmit = (e) => {
    e.preventDefault();
    if (loginForm.username && loginForm.password) {
      setIsLoggedIn(true);
      setShowLoginModal(false);
      setRunConfetti(true);
      setTimeout(() => setRunConfetti(false), 5000);
    }
  };

  const calculateTotalPrice = () => {
    let total = selectedPackage.price + extraHours * 50;
    if (droneAddon) total += 150;
    if (albumAddon) total += 100;
    return total;
  };

  const handleBookingSubmit = (e) => {
    e.preventDefault();
    setBookingPopup(true);
  };

  const handleContactSubmit = (e) => {
    e.preventDefault();
    setContactSubmitted(true);
    setTimeout(() => setContactSubmitted(false), 4000);
  };

  // Filter Logic
  const filteredGallery = GALLERY_IMAGES.filter((img) => {
    const matchesCat = selectedCategory === "All" || img.category === selectedCategory;
    const matchesSearch = img.title.toLowerCase().includes(searchQuery.toLowerCase());
    return matchesCat && matchesSearch;
  });

  const displayedImages = activeTab === "favorites"
    ? GALLERY_IMAGES.filter((img) => favorites.includes(img.id))
    : filteredGallery;

  return (
    <div className="app-container">
      {runConfetti && <Confetti width={window.innerWidth} height={window.innerHeight} recycle={false} numberOfPieces={400} />}

      {/* Sticky Navbar */}
      <nav className="navbar">
        <div className="nav-brand" onClick={() => setActiveTab("home")}>📷 SHUTTER STORIES</div>
        <div className="nav-right-controls">
          <button className="theme-btn" onClick={() => setDarkMode(!darkMode)}>
            {darkMode ? "☀️ Light" : "🌙 Dark"}
          </button>
          <button className="hamburger" onClick={() => setMenuOpen(!menuOpen)}>☰</button>
        </div>
        <ul className={`nav-links ${menuOpen ? "open" : ""}`}>
          {["home", "gallery", "services", "packages", "photographer", "favorites", "booking", "about", "contact"].map((tab) => (
            <li key={tab}>
              <button
                className={activeTab === tab ? "active" : ""}
                onClick={() => { setActiveTab(tab); setMenuOpen(false); }}
              >
                {tab.charAt(0).toUpperCase() + tab.slice(1)} {tab === "favorites" ? `(${favorites.length})` : ""}
              </button>
            </li>
          ))}
          <li>
            {isLoggedIn ? (
              <button className="auth-btn logout-btn" onClick={() => setIsLoggedIn(false)}>Logout</button>
            ) : (
              <button className="auth-btn login-btn" onClick={() => setShowLoginModal(true)}>Login</button>
            )}
          </li>
        </ul>
      </nav>

      {/* 1. Home Page */}
      {activeTab === "home" && (
        <>
          <section className="hero-section">
            <div className="hero-backdrop">
              <img src={getImagePath("hero-bg.jpg")} alt="Hero Background" onError={(e) => { e.target.src = "https://images.unsplash.com/photo-1542038784456-1ea8e935640e?w=1200"; }} />
              <div className="hero-overlay"></div>
            </div>
            <div className="hero-content">
              <h1>Capturing Timeless Moments</h1>
              <p>Professional photography services for Weddings, Events, and Portraits.</p>
              <button className="btn-primary" onClick={() => setActiveTab("booking")}>Book a Session Now</button>
            </div>
          </section>

          {/* Image Slider */}
          <section>
            <h2 className="section-title">Featured Highlights</h2>
            <div className="slider-container">
              <img src={getImagePath(GALLERY_IMAGES[currentSlide].filename)} alt="Slide" className="slide-img" onError={(e) => { e.target.src = "https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=800"; }} />
              <div className="slider-caption">{GALLERY_IMAGES[currentSlide].title} ({GALLERY_IMAGES[currentSlide].category})</div>
              <button className="slider-btn left" onClick={() => setCurrentSlide((prev) => (prev === 0 ? 4 : prev - 1))}>❮</button>
              <button className="slider-btn right" onClick={() => setCurrentSlide((prev) => (prev + 1) % 5)}>❯</button>
            </div>
          </section>

          {/* Testimonials */}
          <section>
            <h2 className="section-title">Client Testimonials</h2>
            <div className="testimonial-box">
              <p>"{TESTIMONIALS[currentSlide % TESTIMONIALS.length].quote}"</p>
              <h4>- {TESTIMONIALS[currentSlide % TESTIMONIALS.length].name}</h4>
            </div>
          </section>
        </>
      )}

      {/* 2. Portfolio / Favorites */}
      {(activeTab === "gallery" || activeTab === "favorites") && (
        <section>
          <h2 className="section-title">{activeTab === "favorites" ? "Your Favorites" : "Portfolio Gallery"}</h2>

          {activeTab !== "favorites" && (
            <div className="controls-bar">
              <input type="text" placeholder="Search photos..." className="search-input" value={searchQuery} onChange={(e) => setSearchQuery(e.target.value)} />
              <div className="filter-bar">
                {CATEGORIES.map((cat) => (
                  <button key={cat} className={`filter-btn ${selectedCategory === cat ? "active" : ""}`} onClick={() => setSelectedCategory(cat)}>
                    {cat}
                  </button>
                ))}
              </div>
            </div>
          )}

          <div className="gallery-grid">
            {displayedImages.length > 0 ? (
              displayedImages.map((img) => (
                <div className="gallery-card" key={img.id}>
                  <div className="img-wrapper">
                    <img src={getImagePath(img.filename)} alt={img.title} onError={(e) => { e.target.src = "https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=600"; }} onClick={() => setActiveLightbox(img)} />
                  </div>
                  <div className="card-info">
                    <span>{img.title}</span>
                    <button className="fav-btn" onClick={() => toggleFavorite(img.id)}>
                      {favorites.includes(img.id) ? "❤️" : "🤍"}
                    </button>
                  </div>
                </div>
              ))
            ) : (
              <p>No photos found.</p>
            )}
          </div>
        </section>
      )}

      {/* 3. Services */}
      {activeTab === "services" && (
        <section>
          <h2 className="section-title">Our Photography Services</h2>
          <div className="services-grid">
            {SERVICES.map((srv, idx) => (
              <div className="service-card" key={idx}>
                <h3>{srv.title}</h3>
                <p>{srv.desc}</p>
              </div>
            ))}
          </div>
        </section>
      )}

      {/* 4. Packages & Dynamic Calculator */}
      {activeTab === "packages" && (
        <section>
          <h2 className="section-title">Packages & Pricing</h2>
          <div className="packages-grid">
            {PACKAGES.map((pkg) => (
              <div key={pkg.id} className={`package-card ${selectedPackage.id === pkg.id ? "selected" : ""}`}>
                <h3>{pkg.name}</h3>
                <p className="price">${pkg.price}</p>
                <ul>
                  {pkg.features.map((feat, idx) => <li key={idx}>✓ {feat}</li>)}
                </ul>
                <button className="btn-primary" onClick={() => setSelectedPackage(pkg)}>Select Package</button>
              </div>
            ))}
          </div>

          <div className="calc-box">
            <h3>⚡ Dynamic Pricing Calculator</h3>
            <p>Selected Base Package: <strong>{selectedPackage.name} (${selectedPackage.price})</strong></p>
            <div className="calc-options">
              <label>Extra Hours ($50/hr): 
                <input type="number" min="0" value={extraHours} onChange={(e) => setExtraHours(Number(e.target.value))} style={{ marginLeft: "10px", width: "60px" }} />
              </label>
              <label><input type="checkbox" checked={droneAddon} onChange={(e) => setDroneAddon(e.target.checked)} /> Add Drone Coverage (+$150)</label>
              <label><input type="checkbox" checked={albumAddon} onChange={(e) => setAlbumAddon(e.target.checked)} /> Premium Printed Album (+$100)</label>
            </div>
            <h4>Total Calculated Price: <span style={{ color: "var(--primary-color)" }}>${calculateTotalPrice()}</span></h4>
            <button className="btn-primary" onClick={() => setActiveTab("booking")}>Proceed to Booking</button>
          </div>
        </section>
      )}

      {/* 5. Photographer Profile */}
      {activeTab === "photographer" && (
        <section>
          <h2 className="section-title">Meet Your Photographer</h2>
          <div className="photographer-card">
            <img src={getImagePath("images (7).jpg")} alt="Photographer" onError={(e) => { e.target.src = "https://images.unsplash.com/photo-1534528741775-53994a69daeb?w=400"; }} />
            <div>
              <h3>Alex Rivera</h3>
              <p>Lead Photographer & Creative Director with over 8 years of international experience capturing luxury weddings, portraits, and travel stories.</p>
            </div>
          </div>
        </section>
      )}

      {/* 6. Booking */}
      {activeTab === "booking" && (
        <section>
          <h2 className="section-title">Book a Photography Session</h2>
          <div className="form-container">
            <form onSubmit={handleBookingSubmit}>
              <div className="form-group">
                <label>Full Name</label>
                <input type="text" required value={bookingDetails.name} onChange={(e) => setBookingDetails({ ...bookingDetails, name: e.target.value })} />
              </div>
              <div className="form-group">
                <label>Email Address</label>
                <input type="email" required value={bookingDetails.email} onChange={(e) => setBookingDetails({ ...bookingDetails, email: e.target.value })} />
              </div>
              <div className="form-group">
                <label>Photography Category</label>
                <select value={bookingDetails.category} onChange={(e) => setBookingDetails({ ...bookingDetails, category: e.target.value })}>
                  {CATEGORIES.filter(c => c !== "All").map(c => <option key={c} value={c}>{c}</option>)}
                </select>
              </div>
              <div className="form-group">
                <label>Preferred Date</label>
                <input type="date" required value={bookingDetails.date} onChange={(e) => setBookingDetails({ ...bookingDetails, date: e.target.value })} />
              </div>
              <div className="form-group">
                <label>Preferred Time</label>
                <input type="time" required value={bookingDetails.time} onChange={(e) => setBookingDetails({ ...bookingDetails, time: e.target.value })} />
              </div>
              <h4>Package: {selectedPackage.name} | Total Estimated Cost: ${calculateTotalPrice()}</h4>
              <button type="submit" className="btn-primary" style={{ width: "100%" }}>Confirm Booking</button>
            </form>
          </div>
        </section>
      )}

      {/* 7. About */}
      {activeTab === "about" && (
        <section>
          <h2 className="section-title">About Shutter Stories</h2>
          <p style={{ textAlign: "center", maxWidth: "800px", margin: "0 auto" }}>
            Shutter Stories is a premier photography agency dedicated to crafting visual narratives. From intimate portraits to grand wedding celebrations, we blend artistic aesthetics with modern technology to preserve your finest moments forever.
          </p>
        </section>
      )}

      {/* 8. Contact */}
      {activeTab === "contact" && (
        <section>
          <h2 className="section-title">Contact Us</h2>
          <div className="form-container">
            {contactSubmitted && <p style={{ color: "green" }}>Message sent successfully! We will get back to you soon.</p>}
            <form onSubmit={handleContactSubmit}>
              <div className="form-group">
                <label>Name</label>
                <input type="text" required value={contactMsg.name} onChange={(e) => setContactMsg({ ...contactMsg, name: e.target.value })} />
              </div>
              <div className="form-group">
                <label>Email</label>
                <input type="email" required value={contactMsg.email} onChange={(e) => setContactMsg({ ...contactMsg, email: e.target.value })} />
              </div>
              <div className="form-group">
                <label>Message</label>
                <textarea rows="4" required value={contactMsg.message} onChange={(e) => setContactMsg({ ...contactMsg, message: e.target.value })}></textarea>
              </div>
              <button type="submit" className="btn-primary" style={{ width: "100%" }}>Send Message</button>
            </form>
          </div>
        </section>
      )}

      {/* Modals */}
      {showLoginModal && (
        <div className="modal-overlay" onClick={() => setShowLoginModal(false)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <button className="close-btn" onClick={() => setShowLoginModal(false)}>✕</button>
            <h3>Sign In / Register</h3>
            <form onSubmit={handleLoginSubmit}>
              <div className="form-group">
                <input type="text" placeholder="Username" required value={loginForm.username} onChange={(e) => setLoginForm({ ...loginForm, username: e.target.value })} />
              </div>
              <div className="form-group">
                <input type="password" placeholder="Password" required value={loginForm.password} onChange={(e) => setLoginForm({ ...loginForm, password: e.target.value })} />
              </div>
              <button type="submit" className="btn-primary" style={{ width: "100%" }}>Login</button>
            </form>
          </div>
        </div>
      )}

      {activeLightbox && (
        <div className="modal-overlay" onClick={() => setActiveLightbox(null)}>
          <div className="lightbox-content">
            <button className="close-btn" style={{ color: "white" }} onClick={() => setActiveLightbox(null)}>✕</button>
            <img src={getImagePath(activeLightbox.filename)} alt={activeLightbox.title} onError={(e) => { e.target.src = "https://images.unsplash.com/photo-1518709268805-4e9042af9f23?w=800"; }} />
          </div>
        </div>
      )}

      {bookingPopup && (
        <div className="modal-overlay" onClick={() => setBookingPopup(false)}>
          <div className="modal-content">
            <button className="close-btn" onClick={() => setBookingPopup(false)}>✕</button>
            <h3>🎉 Booking Confirmed!</h3>
            <p>Thank you, <strong>{bookingDetails.name}</strong>!</p>
            <p>Your <strong>{bookingDetails.category}</strong> session date is <strong>{bookingDetails.date}</strong> at <strong>{bookingDetails.time}</strong>.</p>
            <p>Total Cost: <strong>${calculateTotalPrice()}</strong></p>
            <button className="btn-primary" onClick={() => setBookingPopup(false)}>Close</button>
          </div>
        </div>
      )}

      {/* Scroll-To-Top Button */}
      <button className="scroll-to-top" onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}>↑</button>

      {/* Footer */}
      <footer className="footer">
        <div className="footer-socials">
          <a href="https://wa.me/1234567890" target="_blank" rel="noopener noreferrer">
            <img src="https://upload.wikimedia.org/wikipedia/commons/6/6b/WhatsApp.svg" alt="WhatsApp" className="social-icon" />
          </a>
          <a href="https://www.tiktok.com/" target="_blank" rel="noopener noreferrer">
